<template><SilkRoadWorkspace title="工作台总览"><template #actions><el-button type="primary" @click="router.push('/projects/create')">创建营销项目</el-button></template><section class="hero"><div><span>DIGITAL SILK ROAD</span><h1>跨境电商 AI Agent 智能营销引擎</h1><p>从商品理解、目标市场合规、本地化营销内容，到图片、视频、数字人生成与数据反馈的一体化工作台。</p><div><el-button type="primary" size="large" @click="router.push('/agent')">运行丝路 Agent</el-button><el-button size="large" @click="router.push('/projects')">查看营销项目</el-button></div></div><el-icon><Promotion/></el-icon></section><section v-loading="loading" class="metrics"><article v-for="item in metricItems" :key="item.label"><el-icon><component :is="item.icon"/></el-icon><div><strong>{{ item.value }}</strong><span>{{ item.label }}</span></div></article></section><section class="section"><h2>主业务闭环</h2><div class="flow"><button v-for="(item,index) in flow" :key="item.title" @click="router.push(item.path)"><span>{{ index+1 }}</span><div><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div><el-icon><ArrowRight/></el-icon></button></div></section><section class="section"><h2>快捷入口</h2><div class="quick"><button v-for="item in quick" :key="item.title" @click="router.push(item.path)"><el-icon><component :is="item.icon"/></el-icon><strong>{{ item.title }}</strong><p>{{ item.description }}</p></button></div></section></SilkRoadWorkspace></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ArrowRight,DataAnalysis,FolderOpened,MagicStick,Picture,Promotion,Timer,User,VideoPlay}from'@element-plus/icons-vue';import{useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{workbenchAPI}from'@/api/workbench';import type{WorkbenchSummary}from'@/types/workbench';const router=useRouter(),summary=ref<WorkbenchSummary>(),loading=ref(false);const metricItems=computed(()=>[{label:'营销项目',value:summary.value?.overview.totalProjects??0,icon:FolderOpened},{label:'生成图片',value:summary.value?.overview.imagesGenerated??0,icon:Picture},{label:'生成视频',value:summary.value?.overview.videosGenerated??0,icon:VideoPlay},{label:'处理中任务',value:summary.value?.overview.processingTasks??0,icon:Timer}]);const flow=[{title:'Agent 智能分析',description:'识别商品与目标市场',path:'/agent'},{title:'创建营销项目',description:'沉淀商品和营销方案',path:'/projects/create'},{title:'合规与内容生产',description:'生成脚本、分镜和素材',path:'/projects'},{title:'数据分析',description:'跟踪表现并持续优化',path:'/analytics'}];const quick=[{title:'合规中心',description:'目标市场规则与风险分析',path:'/compliance',icon:DataAnalysis},{title:'媒体生成',description:'商品图片与营销视频素材',path:'/media/image',icon:MagicStick},{title:'数字人中心',description:'商品讲解人与品牌口播',path:'/digital-human',icon:User},{title:'营销项目',description:'查看项目、任务和素材',path:'/projects',icon:FolderOpened}];onMounted(async()=>{loading.value=true;try{summary.value=await workbenchAPI.summary()}finally{loading.value=false}})</script>
<style scoped>.hero{display:grid;grid-template-columns:1fr auto;align-items:center;gap:30px;padding:38px;border-radius:26px;background:linear-gradient(120deg,#102a5c,#4456d8);color:#fff}.hero span{font-size:12px;letter-spacing:.18em;color:#93c5fd}.hero h1{font-size:38px;max-width:800px;margin:10px 0}.hero p{max-width:780px;color:rgba(255,255,255,.74);line-height:1.7;margin-bottom:22px}.hero>.el-icon{font-size:112px;opacity:.2}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:20px 0}.metrics article{display:flex;align-items:center;gap:14px;padding:20px;border:1px solid var(--border-primary);border-radius:17px;background:var(--bg-card)}.metrics .el-icon{font-size:30px;color:var(--accent)}.metrics strong,.metrics span{display:block}.metrics strong{font-size:26px}.metrics span{font-size:13px;color:var(--text-muted)}.section{margin-top:28px}.section h2{margin-bottom:16px}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.flow button{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;text-align:left;padding:17px;border:1px solid var(--border-primary);border-radius:15px;background:var(--bg-card);color:var(--text-primary)}.flow button>span{width:28px;height:28px;display:grid;place-items:center;border-radius:50%;background:var(--accent);color:#fff}.flow p,.quick p{margin-top:5px;color:var(--text-secondary);font-size:13px}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.quick button{padding:21px;text-align:left;border:1px solid var(--border-primary);border-radius:16px;background:var(--bg-card);color:var(--text-primary)}.quick .el-icon{font-size:28px;color:var(--accent);margin-bottom:14px}.quick strong{display:block}@media(max-width:1000px){.metrics,.flow,.quick{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.hero>.el-icon{display:none}.hero h1{font-size:29px}.metrics,.flow,.quick{grid-template-columns:1fr}}</style>
